package org.local.donusturucu.qa;
import android.app.*;import android.content.*;import android.os.*;import android.net.Uri;import android.provider.DocumentsContract;import android.view.KeyEvent;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import org.json.*;
public class FolderSpeechMemory extends FolderBatch {
 String stage="startup";void require(boolean value)throws Exception{if(!value)throw new IOException(stage);}
 File copy(String name,File root)throws Exception{File f=new File(root,name);InputStream in=getContext().getAssets().open(name);OutputStream out=new FileOutputStream(f);try{byte[]buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}finally{in.close();out.close();}return f;}
 public void onStart(){Bundle result=new Bundle();try{Intent intent=new Intent();intent.setClassName("org.local.donusturucu","org.local.donusturucu.MainActivity");intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);activity=startActivitySync(intent);long until=System.currentTimeMillis()+60000;while(!(Boolean)get("ready")&&System.currentTimeMillis()<until)Thread.sleep(200);require((Boolean)get("ready"));final Uri tree=(Uri)get("outputTree");require(tree!=null);Uri parent=DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));File root=new File(getTargetContext().getExternalFilesDir(null),"folder-speech-memory-test");root.mkdirs();JSONArray rows=new JSONArray();
 for(int repeat=1;repeat<=3;repeat++)for(final String language:new String[]{"tr","en"}){invoke("clearFiles");File shortFile=copy("short-"+language+".wav",root),longFile=copy("long-"+language+".wav",root),text=new File(root,"note.txt");SubtitleRoundtrip.write(text,"Not audio");String shortHash=hash(shortFile),longHash=hash(longFile),textHash=hash(text);final List<Uri>uris=Arrays.asList(Uri.fromFile(shortFile),Uri.fromFile(longFile),Uri.fromFile(text));ui(new Runnable(){public void run(){try{call("importMany",new Class<?>[]{List.class,Uri.class},uris,null);}catch(Exception error){throw new RuntimeException(error);}}});until=System.currentTimeMillis()+60000;while((Boolean)get("busy")&&System.currentTimeMillis()<until){Thread.sleep(100);waitForIdleSync();}stage="import count="+((List)get("files")).size();require(!(Boolean)get("busy")&&((List)get("files")).size()==3);final Set<String>before=children(tree,parent);
 ui(new Runnable(){public void run(){try{call("selectFile",new Class<?>[]{int.class},0);set("action","transcribe");call("buildActions",new Class<?>[]{});((Spinner)get("recognitionLanguage")).setSelection(language.equals("en")?1:0);((Spinner)get("speechOutput")).setSelection(1);call("startJob",new Class<?>[]{});}catch(Exception error){throw new RuntimeException(error);}}});until=System.currentTimeMillis()+300000;while((Boolean)get("busy")&&System.currentTimeMillis()<until){Thread.sleep(200);waitForIdleSync();}require(!(Boolean)get("busy"));Set<String>added=children(tree,parent);added.removeAll(before);stage="outputs="+added.size()+" status="+((TextView)get("status")).getText()+" log="+get("log");require(added.isEmpty());require(get("log").toString().contains("1,5 GB"));int longCues=0;stage="original hash";require(shortHash.equals(hash(shortFile))&&longHash.equals(hash(longFile))&&textHash.equals(hash(text)));sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);waitForIdleSync();JSONObject row=new JSONObject();row.put("repeat",repeat);row.put("language",language);row.put("outputs",0);row.put("low_memory_message",true);row.put("non_audio_skipped",true);row.put("long_cues",longCues);row.put("originals_unchanged",true);row.put("pass",true);rows.put(row);JSONObject report=new JSONObject();report.put("cases",rows.length());report.put("failures",0);report.put("rows",rows);SubtitleRoundtrip.write(new File(root,"report.json"),report.toString(2));}
 invoke("clearFiles");finish(0,result);
 }catch(Throwable error){result.putString("error",error.toString());if(error instanceof InvocationTargetException)result.putString("cause",((InvocationTargetException)error).getCause().toString());finish(1,result);}}
}
